  // 1. Arrange (Preparar)
  render(<Counter initial={0} />);

  const button = screen.getByRole('button', { name: /sumar/i });
  const result = screen.getByText(/total: 0/i);

  // 2. Act (Actuar)
  await userEvent.click(button);

